  const grid=$('#app .pets');if(grid)grid.innerHTML=activePosts().slice(0,3).map(card).join('');
  if(!data.announcementClosed){const banner=document.createElement('div');banner.className='notice';banner.style.marginBottom='15px';banner.innerHTML=`<button style="float:right" onclick="data.announcementClosed=true;save();render()">×</button><button onclick="go('announcement')">◉ 成都互助提醒：核实认领材料，保护宠物安全 ›</button>`;$('#app').prepend(banner)}
