function fillExpandedPet(i){const p=data.pets[i];if(!p)return;const f=$('#postForm');for(const [k,v] of Object.entries({name:p.name,breed:p.breed||p.kind?.split(' · ')[0],gender:p.gender||'未知',petType:p.petType||'猫'}))if(f.elements[k])f.elements[k].value=v}
function saveDraft(){const f=Object.fromEntries(new FormData($('#postForm')));delete f.photos;data.postDraft={...f,type:args.type};save();toast('草稿已保存，可从我的帖子继续')}
function confirmPublish(f){const files=$('[name=photos]').files;if(files.length>9||[...files].some(f=>f.size>5*1024*1024))return toast('图片最多9张，每张不超过5MB');if(!validPhone(f.phone))return toast('请输入有效手机号');if(new Date(f.eventTime)>new Date())return toast('发生时间不能晚于现在');if(args.editId&&byId(args.editId).editCount)return toast('展示中帖子仅可编辑一次');const proceed=img=>go('confirmPost',{type:args.type,form:f,img,editId:args.editId});if(files[0]){const r=new FileReader();r.onload=()=>proceed(r.result);r.readAsDataURL(files[0])}else proceed(args.editId?byId(args.editId).img:cat)}
function finishPublish(){const f=args.form,id=args.editId||Date.now(),old=byId(id);const p={...old,...f,id,type:args.type,reward:Number(f.reward||0),days:Number(f.days||7),img:args.img,status:'待审核',mine:true,editCount:old?(old.editCount||0)+1:0};if(old)data.posts[data.posts.indexOf(old)]=p;else data.posts.unshift(p);if(f.saveAsPet)data.pets.push({name:f.name,kind:f.breed,breed:f.breed,gender:f.gender,petType:f.petType,img:args.img});delete data.postDraft;addNotice('帖子已提交审核',{post:id});go('myPosts')}
function simulateAudit(id,pass){const p=byId(id);p.status=pass?'展示中':'已驳回';addNotice(pass?'帖子已通过审核，可按需支付悬赏':'帖子被驳回，请完善内容后重新提交',{post:id});render()}
function extendPost(id){const p=byId(id);if(p.extended)return toast('每帖只能延长一次');p.extended=true;save();toast('已模拟延长一次，不重复收取服务费');render()}
function takeDown(id){const p=byId(id);if(p.rewardPaid&&!p.found)return toast('存在未结悬赏，请先处理资金与线索');p.status='已下架';save();go('myPosts')}
function simulateRewardPay(id){const p=byId(id);p.rewardPaid=true;p.status='悬赏托管中';p.expiry=Date.now()+(p.days||7)*86400000;data.payments.unshift({id:Date.now(),type:'悬赏',amount:p.reward+Math.min(p.reward*.08,80),status:'已托管',post:id});addNotice('模拟悬赏支付成功',{post:id});go('managePost',{id})}
function buyTop(id,price,days){const p=byId(id);if(!['展示中','悬赏托管中'].includes(p.status))return toast('请审核通过后再置顶');p.topUntil=Date.now()+days*86400000;data.payments.unshift({id:Date.now(),type:'置顶',amount:price,status:'演示生效',post:id});save();go('orders')}
function freeTop(id){const p=byId(id);if(p.freeApplied)return toast('每帖只能申请一次');const month=new Date().toISOString().slice(0,7);data.freeMonths??={};if((data.freeMonths[month]||0)>=2)return toast('本月申请次数已达2次');p.freeApplied=true;data.freeMonths[month]=(data.freeMonths[month]||0)+1;save();toast('免费置顶申请已提交人工核验')}
function seedClue(post){data.ownClues.push({id:Date.now(),post,author:'热心邻居'+(data.ownClues.length+1),content:'在玉林附近看到相似宠物，有现场情况可供核实。',status:'待确认'});save();render()}
function markClue(id,on){const c=data.ownClues.find(c=>c.id===id);if(on&&data.ownClues.filter(x=>x.post===c.post&&x.status==='有效').length>=5)return toast('有效线索最多5条');c.status=on?'有效':'无效';save();render()}
function finishFound(id,form){const p=byId(id);p.found=true;p.story=form.story.value;p.status=p.rewardPaid?'待评分核验':'已完成';p.splitStatus='待人工核验';addNotice('找回已确认，悬赏不再进入未找回退款流程',{post:id});go('found')}
addClue=function(f){if(!validPhone(f.phone))return toast('手机号格式不正确');const p=selectedPost();if(p.mine)return toast('不能给自己的帖子提供线索');if(data.clues.filter(c=>c.post===args.id).length>=3)return toast('同一帖子最多提交3条线索');data.clues.unshift({post:args.id,content:f.content,phone:f.phone});addNotice('线索已提交，若已协助找回而存在争议，可提交证据',{post:args.id});go('myClues')};
addClaim=function(f){if(!validPhone(f.phone))return toast('手机号格式不正确');if($('[name=proof]').files.length<2)return toast('至少上传2张证明材料');if(data.claims.filter(c=>c.post===args.id).length>=20)return toast('该帖申请数已达上限');data.claims.push({id:Date.now(),post:args.id,content:f.content,status:'待审核'});addNotice('认领申请已提交，等待审核');go('myClaims')};
function cConfirm(id,on){const c=data.claims.find(c=>c.id===id);c.status=on?'已确认':'已拒绝';save();render()}
function addRequestV14(f){if(!validPhone(f.phone))return toast('请输入有效手机号');if(new Date(f.time)<=new Date())return toast('请选择未来时间');if(f.serviceType==='按日上门'&&(!f.endTime||new Date(f.endTime)<=new Date(f.time)||!f.dailyTime))return toast('请填写有效结束时间和每日时段');data.requests.unshift({...f,pet:data.pets[Number(f.pet)]?.name||'爱宠',feeder:args.feeder,status:'待响应',id:Date.now()});addNotice('喂养请求已提交，48小时未响应自动关闭');go('requests')}
function savePetV14(f){const file=$('[name=avatar]').files[0];const complete=img=>{const p={...data.pets[args.index],id:data.pets[args.index]?.id||Date.now(),...f,img,kind:f.breed+(f.birthday?' · '+f.birthday:'')};if(args.index!==undefined)data.pets[args.index]=p;else data.pets.push(p);save();go('pets')};if(file){if(file.size>5*1024*1024)return toast('图片请小于5MB');const reader=new FileReader();reader.onload=()=>complete(reader.result);reader.readAsDataURL(file)}else complete(data.pets[args.index]?.img||cat)}
function deletePet(i){data.pets.splice(i,1);save();go('pets')}
function simulateAvatar(form){const p=data.pets[args.index];if((p.avatarUsed||0)>=3)return toast('免费次数已用完，价格待配置');const b=form.querySelector('button');b.disabled=true;b.textContent='生成流程演示中…';const index=args.index,style=form.elements.style.value;setTimeout(()=>{p.avatarUsed=(p.avatarUsed||0)+1;p.aiDemo=true;data.avatarHistory.push({petId:p.id,style,time:localTime()});save();go('pets',{index});toast('演示完成，展示通用插画，并非真实AI结果')},1200)}
function readNotice(i){const m=data.messages[i];m.read=true;save();if(m.feedbackId)go('feedbackDetail',{id:m.feedbackId});else if(m.post)go('detail',{id:m.post});else render()}
function sendChat(text){if(/1[3-9][\s\d-]{9,}|https?:\/\/|微信|加微|收款|转账|二维码|wx[:：]/i.test(text))return toast('请勿发送联系方式、外链或私下付款信息');const c=data.chats.find(c=>c.post===args.id);c.texts.push({text,mine:true,time:localTime()});save();render()}
function feederAction(id,status){const r=data.requests.find(r=>r.id===id);if(status==='已完成'&&r.status!=='已联系')return toast('先标记已联系');r.status=status;save();render()}
function cancelDemoAccount(){if(data.posts.some(p=>p.mine&&!['已下架','已完成','已过期'].includes(p.status))||data.requests.some(r=>!['已完成','已关闭'].includes(r.status))||data.payments.some(p=>p.status==='已托管'))return toast('存在进行中业务，请先完成处置');data.phoneBound=false;save();go('home');toast('模拟注销完成')}
render();

card=function(p){const paid=p.rewardPaid||p.status==='悬赏托管中';return `<button class="pet" onclick="go('detail',{id:${p.id}})"><img src="${p.img}" alt="${esc(p.name)}"><div><strong>${esc(p.name)} · ${esc(p.type)}</strong><span class="orange">${paid&&p.reward?'悬赏 ¥'+p.reward:'免费互助'}</span><br><small>${esc(p.district)}</small></div></button>`};
render();
